mapper.select:
SELECT point
FROM USERS
WHERE id = #{userId}

mapper.update:
UPDATE USERS
SET point = point - #{price}
WHERE id = #{userId}
  AND point >= #{price}

UPDATE USERS
SET point = point + #{amount}
WHERE id = #{userId}

mapper.delete:
DELETE FROM USER_INVENTORY
WHERE id = #{inventoryId}
  AND user_id = #{userId}
  AND status = 'USED'

mapper.update:
UPDATE USER_INVENTORY
SET status = 'USED'
WHERE id = #{inventoryId}
  AND user_id = #{userId}
  AND status = 'AVAILABLE'
